    'private_terms_13' => 'use our services, in particular, play games and place bets;',
    'private_terms_14' => 'chat and communicate with other players;',
    'private_terms_15' => 'subscribe to a weekly newsletter;',
    'private_terms_16' => 'create, manage, and close an account.',
    'private_terms_17' => 'In the profile settings on our website, the player can:',
